SELECT id, customer_id, created_at, coupon_codes, AGGREGATE(items, 0.0D, (acc, item) -> acc + item.qty * item.price, acc -> ROUND(acc, 2)) AS items_total, TRANSFORM(FILTER(items, item -> item.promo IS NOT NULL), item -> STRUCT(item.product_id AS pid, ROUND(item.price * 0.9, 2) AS discounted_price)) AS promo_lines, COALESCE(attributes['device'], 'direct') AS device_or_default, EXISTS(coupon_codes, c -> c LIKE 'W%') AS has_welcome_code, attributes['device'] AS device FROM carts WHERE ARRAY_CONTAINS(coupon_codes, 'WELCOME5');
